import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Geometry based on atlas region aspect ratio (512x320)
  const ATLAS_WIDTH = 512;
  const ATLAS_HEIGHT = 320;
  const aspect = ATLAS_WIDTH / ATLAS_HEIGHT; // 1.6
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic material; texture will be assigned asynchronously
  const material = new MeshBasicNodeMaterial({ transparent: true });
  let loadedTexture = null;

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Billboard toward camera each frame
  root.onBeforeRender = (renderer, scene, camera) => {
    root.lookAt(camera.position);
  };

  // Add text if any (headline role)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 39,
      color: ctx.primitives?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text ?? '', opts);
    textGroup.add(txt);
  }
  if (textGroup.children.length) {
    // Position text slightly above plane surface
    textGroup.position.set(0, 0.55, 0.01);
    root.add(textGroup);
  }

  // Apply cinematic primitives if any
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created elsewhere
    if (gsap && typeof gsap.globalTimeline?.killChildren === 'function') {
      gsap.globalTimeline.killChildren();
    }
  };

  // No event handlers required for this node (static composition)

  return root;
}
